<script setup>
import { ref, onMounted } from 'vue'
import { api } from '../api/ApiClient.js'
import Icon from '../components/AppIcon.vue'
const emit = defineEmits(['error'])
const report = ref(null)
onMounted(async () => { try { report.value = await api.get('/api/evaluation') } catch (e) { emit('error', e.message) } })
const pct = value => value == null ? '—' : `${(value * 100).toFixed(1)}%`
</script>
<template><section class="page-content"><div class="page-title"><span class="eyebrow">MEASURE, DON'T ASSUME</span><h1>评测与质量</h1><p>用可复现的记录检查检索、路由和回答边界。</p></div>
  <div v-if="!report?.available" class="empty-page"><Icon name="chart" :size="36" /><h2>{{ report ? '评测尚未运行' : '读取评测记录…' }}</h2><p>完成本地评测后，这里会展示真实结果。</p></div>
  <template v-else><div v-if="report.stale" class="notice" role="status">这份评测使用的是旧索引，尚未覆盖当前数据版本。</div><div class="notice">{{ report.scope }}</div><div class="metric-grid"><article><span>回归用例</span><strong>{{ report.case_count }}</strong><small>含两种模式的场景查询</small></article><article><span>路由准确率</span><strong>{{ pct(report.routing_accuracy) }}</strong><small>规则回归集</small></article><article><span>安全边界通过率</span><strong>{{ pct(report.safety_pass_rate) }}</strong><small>预设场景测试</small></article><article><span>来源集合</span><strong>{{ report.source_count }}</strong><small>不等于医学金标准</small></article></div>
  <div class="section-heading"><h2>检索消融对比</h2><span class="muted">相同问题 · 相同证据集合</span></div><div class="table-wrap"><table><thead><tr><th>配置</th><th>Recall@5</th><th>MRR</th><th>nDCG@5</th><th>平均耗时</th></tr></thead><tbody><tr v-for="row in report.ablations" :key="row.name"><td><b>{{ row.name }}</b><small>{{ row.note }}</small></td><td>{{ pct(row.recall_at_5) }}</td><td>{{ row.mrr?.toFixed(3) || '—' }}</td><td>{{ row.ndcg_at_5?.toFixed(3) || '—' }}</td><td>{{ row.latency_ms?.toFixed(0) || '—' }} ms</td></tr></tbody></table></div>
  <div v-if="report.pipelines?.length" class="table-wrap"><table><thead><tr><th>回答流程</th><th>路由通过率</th><th>平均轮数</th><th>模型调用</th><th>平均耗时</th></tr></thead><tbody><tr v-for="pipeline in report.pipelines" :key="pipeline.name"><td>{{ pipeline.name }}</td><td>{{ pct(pipeline.routing_accuracy) }}</td><td>{{ pipeline.mean_rounds.toFixed(2) }}</td><td>{{ pipeline.model_calls }}</td><td>{{ pipeline.mean_latency_ms.toFixed(0) }} ms</td></tr></tbody></table></div><div class="section-heading"><h2>逐条结果</h2><span class="muted">{{ report.created_at }}</span></div><div class="evaluation-cases"><div v-for="item in report.cases" :key="item.question + item.mode"><Icon :name="item.passed ? 'check' : 'warning'" /><span>{{ item.question }}<small class="muted"> · {{ item.mode === 'exploratory' ? '探索' : '权威' }}</small></span><span class="tag" :class="{ amber: !item.passed }">{{ item.actual }}</span></div></div><p class="subtle">{{ report.limitations }}</p></template>
  <template v-if="report?.answer_quality"><div class="section-heading"><h2>回答质量回归</h2><span class="muted">{{ report.answer_quality.passed }} / {{ report.answer_quality.case_count }} 通过</span></div><p class="notice">{{ report.answer_quality.scope }} {{ report.answer_quality.llm ? '已调用实际生成与检查模型。' : '仅验证离线路由与摘录。' }}{{ report.answer_quality.stale ? ' 数据版本已变化，需重跑。' : '' }}</p><div class="evaluation-cases"><details v-for="(item, i) in report.answer_quality.cases" :key="i"><summary>{{ item.passed ? '✓' : '待改进' }} · {{ item.question }} · {{ item.mode === 'exploratory' ? '探索' : '权威' }}</summary><p style="white-space:pre-wrap;padding:12px">{{ item.answer }}</p><small class="muted">{{ item.generation_mode }} · {{ item.model_calls }} 次模型调用</small></details></div></template>
</section></template>
